"""
Flashcard Trainer with Spaced Repetition

This module implements a flashcard trainer supporting multiple decks, spaced repetition scheduling using an ease factor, and review session management. User progress is saved in JSON format.
"""

import json
import random
from datetime import datetime, timedelta

class Flashcard:
    """Class representing a flashcard with question, answer, and review metadata."""
    def __init__(self, question, answer, interval=1, ease=2.5, repetitions=0, due_date=None):
        self.question = question
        self.answer = answer
        self.interval = interval  # in days
        self.ease = ease  # ease factor influences interval growth
        self.repetitions = repetitions  # number of successful repetitions
        self.due_date = due_date if due_date else datetime.today().date()

    def is_due(self):
        """Check if the card is due for review."""
        return self.due_date <= datetime.today().date()

    def update(self, quality):
        """Update scheduling parameters based on quality of recall from 0 to 5.
        Implements a simplified SuperMemo SM-2 algorithm."""
        if quality < 3:
            self.repetitions = 0
            self.interval = 1
        else:
            if self.repetitions == 0:
                self.interval = 1
            elif self.repetitions == 1:
                self.interval = 6
            else:
                self.interval = int(self.interval * self.ease)
            self.repetitions += 1
        # Update ease factor
        self.ease = max(1.3, self.ease + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)))
        # Set the next due date
        self.due_date = datetime.today().date() + timedelta(days=self.interval)

    def to_dict(self):
        """Serialize the flashcard to dict for JSON storage."""
        return {
            'question': self.question,
            'answer': self.answer,
            'interval': self.interval,
            'ease': self.ease,
            'repetitions': self.repetitions,
            'due_date': self.due_date.isoformat()
        }

    @staticmethod
    def from_dict(data):
        """Deserialize a flashcard from dict."""
        due_date = datetime.fromisoformat(data['due_date']).date() if 'due_date' in data else None
        return Flashcard(
            question=data['question'],
            answer=data['answer'],
            interval=data.get('interval', 1),
            ease=data.get('ease', 2.5),
            repetitions=data.get('repetitions', 0),
            due_date=due_date
        )

class Deck:
    """A collection of flashcards, with progress saved and loaded."""
    def __init__(self, name):
        self.name = name
        self.cards = []

    def add_card(self, flashcard):
        """Add a flashcard to the deck."""
        self.cards.append(flashcard)

    def due_cards(self):
        """Return list of cards that are due for review."""
        return [card for card in self.cards if card.is_due()]

    def to_dict(self):
        """Serialize the deck to dict for JSON storage."""
        return {
            'name': self.name,
            'cards': [card.to_dict() for card in self.cards]
        }

    @staticmethod
    def from_dict(data):
        """Deserialize a deck from dict."""
        deck = Deck(data['name'])
        for card_data in data['cards']:
            deck.add_card(Flashcard.from_dict(card_data))
        return deck

class FlashcardTrainer:
    """Manages multiple decks and review sessions with spaced repetition scheduling."""
    def __init__(self, config_path='config.json', save_path='progress.json'):
        self.decks = {}
        self.config = self.load_config(config_path)
        self.save_path = save_path
        self.load_progress()

    def load_config(self, path):
        """Load configuration including intervals and deck definitions."""
        try:
            with open(path, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Failed to load config: {e}")
            return {}

    def load_progress(self):
        """Load user progress from JSON file."""
        try:
            with open(self.save_path, 'r') as f:
                data = json.load(f)
            for deck_data in data.get('decks', []):
                deck = Deck.from_dict(deck_data)
                self.decks[deck.name] = deck
        except FileNotFoundError:
            # Initialize decks from config if no progress
            for deck_name in self.config.get('decks', {}).keys():
                self.decks[deck_name] = Deck(deck_name)

    def save_progress(self):
        """Save user progress to JSON file."""
        data = {
            'decks': [deck.to_dict() for deck in self.decks.values()]
        }
        with open(self.save_path, 'w') as f:
            json.dump(data, f, indent=2)

    def add_card_to_deck(self, deck_name, question, answer):
        """Add a flashcard to a specified deck."""
        if deck_name not in self.decks:
            self.decks[deck_name] = Deck(deck_name)
        self.decks[deck_name].add_card(Flashcard(question, answer))

    def review_session(self, deck_name):
        """Run a review session for the specified deck."""
        if deck_name not in self.decks:
            print(f"Deck '{deck_name}' not found.")
            return
        deck = self.decks[deck_name]
        due = deck.due_cards()
        if not due:
            print("No cards due for review.")
            return
        print(f"Starting review session for deck '{deck_name}'. {len(due)} cards due.")

        for card in due:
            print(f"\nQuestion: {card.question}")
            input_quality = None
            while input_quality not in ['0','1','2','3','4','5']:
                input_quality = input("Recall quality (0-5): ")
            quality = int(input_quality)
            print(f"Answer: {card.answer}")
            card.update(quality)
        self.save_progress()
        print("Session complete. Progress saved.")

    def stats(self):
        """Print progress statistics about decks and cards."""
        for deck_name, deck in self.decks.items():
            total = len(deck.cards)
            due = len(deck.due_cards())
            print(f"Deck '{deck_name}': {total} cards, {due} due for review.")

if __name__ == '__main__':
    trainer = FlashcardTrainer()
    # Add example cards to test
    if not trainer.decks or all(len(deck.cards) == 0 for deck in trainer.decks.values()):
        trainer.add_card_to_deck('Demo', 'What is the capital of France?', 'Paris')
        trainer.add_card_to_deck('Demo', 'What is 2+2?', '4')
        trainer.save_progress()
    trainer.stats()
    # To test review session uncomment below:
    # trainer.review_session('Demo')
